{"command":"cd /testbed && python3 -c "
import json
r = json.load(open('revocation_report.json'))
def find_comments(o, path=''):
    hits = []
    if isinstance(o, dict):
        for k, v in o.items():
            if k.startswith('_comment_'): hits.append(path + '/' + k)
            hits += find_comments(v, path + '/' + k)
    elif isinstance(o, list):
        for i, v in enumerate(o): hits += find_comments(v, f'{path}[{i}]')
    return hits
print('comment fields remaining:', find_comments(r) or 'NONE')
print('employees:', len(r['employee_details']))
print('total privilege entries:', sum(len(e['privileges']) for e in r['employee_details']))
print('emp_008:', json.dumps([e for e in r['employee_details'] if e['employee_id']=='emp_008'][0], indent=1))
print('emp_009:', json.dumps([e for e in r['employee_details'] if e['employee_id']=='emp_009'][0], indent=1))
" && git status --short 2>/dev/null; ls /testbed"}

